// Personal annotations live only in this browser; original map records remain unchanged.
const MAP_NOTE_KEY='fw-map-notes-v1',MAP_NOTE_ICONS=['关卡','据点','道具','矿石','鱼','神殿'];
let mapNoteMode=false,mapNoteDraft=null,mapNotes=readMapNotes();
function normalizeMapNotes(rows){return Array.isArray(rows)?rows.filter(n=>n&&typeof n.id==='string'&&typeof n.title==='string'&&Number.isFinite(n.x)&&Number.isFinite(n.y)&&n.x>=0&&n.x<=100&&n.y>=0&&n.y<=100).slice(0,300).map(n=>({id:n.id.slice(0,80),title:n.title.slice(0,32),icon:MAP_NOTE_ICONS.includes(n.icon)?n.icon:'关卡',x:n.x,y:n.y})):[]}
function readMapNotes(){try{return normalizeMapNotes(JSON.parse(localStorage.getItem(MAP_NOTE_KEY)||'[]'))}catch{return []}}
function writeMapNotes(rows){try{localStorage.setItem(MAP_NOTE_KEY,JSON.stringify(rows));mapNotes=rows;return true}catch{toast('标记未能保存，请检查浏览器存储空间。');return false}}
function mapNoteEditor(){if(!mapNoteDraft)return '';const n=mapNoteDraft;return `<form class="map-note-editor" id="mapNoteEditor"><div class="map-note-editor-head"><b>${mapNotes.some(p=>p.id===n.id)?'编辑标记':'新建标记'}</b><button type="button" data-note-cancel aria-label="关闭标记编辑">×</button></div><label>标题<input name="title" maxlength="32" required value="${escapeAttr(n.title)}" placeholder="例如：下次来拿材料" autocomplete="off"></label><fieldset><legend>图标</legend><div class="map-note-icons">${MAP_NOTE_ICONS.map(icon=>`<label title="${icon}"><input type="radio" name="icon" value="${icon}" ${icon===n.icon?'checked':''}><span>${atlasIcon(icon)}</span><small>${icon}</small></label>`).join('')}</div></fieldset><div class="map-note-actions"><button type="submit" class="primary">保存标记</button><button type="button" data-note-cancel>取消</button>${mapNotes.some(p=>p.id===n.id)?'<button type="button" class="text-button" data-note-delete>删除标记</button>':''}</div></form>`}
function personalMapPins(){return mapNotes.map(n=>`<button class="pin atlas-pin personal-map-pin" data-map-note="${escapeAttr(n.id)}" style="left:${n.x}%;top:${n.y}%" aria-label="我的标记：${escapeAttr(n.title)}" title="${escapeAttr(n.title)}">${atlasIcon(n.icon)}<span class="pin-label">${esc(n.title)}</span></button>`).join('')}
function paintMapNotes(){const stage=document.querySelector('.atlas-stage');if(!stage)return;const canvas=stage.querySelector('.map-canvas');if(!canvas)return;let layer=stage.querySelector('.personal-map-pins');if(!layer){layer=document.createElement('div');layer.className='map-pins personal-map-pins';canvas.appendChild(layer)}layer.innerHTML=personalMapPins();stage.classList.toggle('map-note-mode',mapNoteMode);const toggle=stage.querySelector('[data-note-mode]');if(toggle){toggle.setAttribute('aria-pressed',String(mapNoteMode));toggle.textContent=mapNoteMode?'点地图放置标记 · 取消':'添加标记'}const host=stage.querySelector('#map-note-editor-host');if(host)host.innerHTML=mapNoteEditor();const list=stage.querySelector('#personal-map-note-list');if(list)list.innerHTML=mapNotes.map(n=>`<button type="button" data-map-note="${escapeAttr(n.id)}">${atlasIcon(n.icon)}<span>${esc(n.title)}</span></button>`).join('')||'<p class="muted">还没有标记。可标记任意位置，也可从地点详情保存。</p>';const count=stage.querySelector('[data-note-count]');if(count)count.textContent=mapNotes.length;}
const mapNotesBasePage=mapPage;
mapPage=function(){let html=mapNotesBasePage();if(!mapLoaded)return html;html=html.replace('<div class="map-results">','<section class="personal-map-notes"><div class="personal-map-notes-head"><h3>我的标记 <small data-note-count>'+mapNotes.length+'</small></h3><button type="button" data-note-mode aria-pressed="'+mapNoteMode+'">添加标记</button></div><small class="muted">仅保存在当前浏览器</small><div id="personal-map-note-list"></div></section><div class="map-results">');return html.replace('<div class="map-viewport"','<div id="map-note-editor-host"></div><div class="map-viewport"')};
const mapNotesBaseDetail=mapPinDetail;
mapPinDetail=function(id){const html=mapNotesBaseDetail(id);return html.replace('<a class="map-pin-source"',`<button type="button" class="button-link" data-note-place="${escapeAttr(id)}">保存为我的标记</button><a class="map-pin-source"`)};
function newMapNote(x,y,title=''){mapNoteMode=false;mapNoteDraft={id:'note-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),title,icon:'关卡',x,y};paintMapNotes();document.querySelector('#map-note-editor-host')?.scrollIntoView({block:'nearest',behavior:'smooth'});document.querySelector('#mapNoteEditor input[name="title"]')?.focus({preventScroll:true})}
function mapNotePoint(clientX,clientY,rect){return {x:Math.max(0,Math.min(100,(clientX-rect.left)/rect.width*100)),y:Math.max(0,Math.min(100,(clientY-rect.top)/rect.height*100))}}
function closeMapNoteEditor(){mapNoteDraft=null;mapNoteMode=false;paintMapNotes()}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-note-mode],[data-note-cancel],[data-note-delete],[data-map-note],[data-note-place]');if(b){e.preventDefault();e.stopImmediatePropagation();if(b.hasAttribute('data-note-mode')){mapNoteMode=!mapNoteMode;mapNoteDraft=null;paintMapNotes();document.querySelector('.map-main')?.scrollIntoView({block:'nearest',behavior:'smooth'})}else if(b.hasAttribute('data-note-cancel'))closeMapNoteEditor();else if(b.hasAttribute('data-note-delete')){if(writeMapNotes(mapNotes.filter(n=>n.id!==mapNoteDraft?.id)))closeMapNoteEditor()}else if(b.hasAttribute('data-note-place')){const p=PINS.find(p=>p.id===b.dataset.notePlace);if(p)newMapNote(p.x,p.y,p.name)}else{const n=mapNotes.find(n=>n.id===b.dataset.mapNote);if(n){mapNoteMode=false;mapNoteDraft={...n};paintMapNotes();document.querySelector('#mapNoteEditor input')?.focus({preventScroll:true})}}return;}if(!mapNoteMode||performance.now()<mapDragUntil||!e.target.closest?.('.atlas-stage .map-viewport')||e.target.closest('.pin'))return;const rect=document.querySelector('.atlas-stage .map-canvas')?.getBoundingClientRect();if(rect?.width&&rect?.height){const p=mapNotePoint(e.clientX,e.clientY,rect);newMapNote(p.x,p.y)}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='mapNoteEditor')return;e.preventDefault();const form=e.target,title=form.elements.title.value.trim();if(!title){form.elements.title.setCustomValidity('请填写标记标题');form.elements.title.reportValidity();return}const icon=form.elements.icon.value,n={...mapNoteDraft,title:title.slice(0,32),icon:MAP_NOTE_ICONS.includes(icon)?icon:'关卡'};if(writeMapNotes([...mapNotes.filter(p=>p.id!==n.id),n])){closeMapNoteEditor();toast('标记已保存在当前浏览器')}});
document.addEventListener('input',e=>{if(e.target.closest?.('#mapNoteEditor')&&e.target.name==='title'){e.target.setCustomValidity('');if(mapNoteDraft)mapNoteDraft.title=e.target.value}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(mapNoteDraft||mapNoteMode))closeMapNoteEditor()});
const mapNotesBaseRender=render;render=function(){const out=mapNotesBaseRender();if(typeof document.querySelector==='function')paintMapNotes();return out};
window.addEventListener('storage',e=>{if(e.key===MAP_NOTE_KEY){mapNotes=readMapNotes();paintMapNotes()}});
if(DB)paintMapNotes();
